using Confluent.Kafka;

var config = new ProducerConfig
{
    BootstrapServers = "localhost:9092",
    Acks = Acks.Leader, // Wait for leader acknowledgment
    CompressionType = CompressionType.Snappy
};

using var producer = new ProducerBuilder<Null, string>(config).Build();

try
{
    var message = new Message<Null, string>
    {
        Value = "User signed up: user-123",
        Timestamp = new Timestamp(DateTime.UtcNow)
    };

    var result = await producer.ProduceAsync("user-events", message);
    Console.WriteLine($"Delivered to {result.TopicPartitionOffset}");
}
catch (ProduceException<Null, string> ex)
{
    Console.WriteLine($"Delivery failed: {ex.Error.Reason}");
}

const { Kafka } = require('kafkajs');

const kafka = new Kafka({
  clientId: 'order-service',
  brokers: ['localhost:9092']
});

const producer = kafka.producer();

async function sendOrder() {
  await producer.connect();

  await producer.send({
    topic: 'orders',
    messages: [
      {
        key: 'order-456',
        value: JSON.stringify({ orderId: 456, total: 99.50 }),
        timestamp: Date.now().toString()
      }
    ]
  });

  console.log('Order message sent');
  await producer.disconnect();
}

sendOrder().catch(console.error);

using Confluent.Kafka;

var config = new ConsumerConfig
{
    BootstrapServers = "localhost:9092",
    GroupId = "order-processors",
    AutoOffsetReset = AutoOffsetReset.Earliest
};

using var consumer = new ConsumerBuilder<Ignore, string>(config).Build();
consumer.Subscribe("orders");

var cts = new CancellationTokenSource();
Console.CancelKeyPress += (_, e) => { e.Cancel = true; cts.Cancel(); };

try
{
    while (!cts.IsCancellationRequested)
    {
        var result = consumer.Consume(cts.Token);
        Console.WriteLine($"Received: {result.Message.Value} from offset {result.Offset}");
        consumer.Commit(result); // Manual commit
    }
}
finally
{
    consumer.Close();
}

const { Kafka } = require('kafkajs');

const kafka = new Kafka({
  clientId: 'analytics-service',
  brokers: ['localhost:9092']
});

const consumer = kafka.consumer({ groupId: 'analytics-readers' });

async function runConsumer() {
  await consumer.connect();

  await consumer.subscribe({ topic: 'user-events', fromBeginning: true });

  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      console.log(`Received: ${message.value} from partition ${partition}`);
    }
  });
}

runConsumer().catch(console.error);
